\begin{itemchoice}
			\itemch Đúng. Ta có $\lim_{x \to -1^+} y = +\infty$ và $\lim_{x \to -1^-} y = -\infty$, nên $x=-1$ là đường tiệm cận đứng.
			\itemch Đúng. Ta có $y' = \dfrac{(2x-1)(x+1) - (x^2-x+7)}{(x+1)^2} = \dfrac{x^2+2x-8}{(x+1)^2}$.
			\itemch Sai. Trên khoảng $(-4;-1)$, đạo hàm $y' < 0$ nên hàm số nghịch biến.
			\itemch Sai. Trên khoảng $(-\infty;-1)$, giá trị lớn nhất của hàm số bằng $-9$ tại $x=-4$.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Đúng. Theo giả thiết $P(A)=0{,}7$.
			\itemch Sai. Ta có $P(AB) = P(A) \cdot P(B|A) = 0{,}7 \cdot 0{,}2 = 0{,}14$.
			\itemch Đúng. $P(B|\bar{A})=0{,}3 \Rightarrow P(\bar{B}|\bar{A}) = 1 - P(B|\bar{A}) = 0{,}7$.
			\itemch Sai. Xác suất ngày chủ nhật trời nắng là $P(\bar{B}) = P(A)P(\bar{B}|A) + P(\bar{A})P(\bar{B}|\bar{A}) = 0{,}7 \cdot 0{,}8 + 0{,}3 \cdot 0{,}7 = 0{,}77$.
		\end{itemchoice}
